// Case 1: Custom deleter - make functions not applicable
struct FileCloser {
    void operator()(FILE* fp) const {
        if (fp) fclose(fp);
    }
};
// std::unique_ptr<FILE, FileCloser> pFile = std::make_unique<FILE, FileCloser>(...); // ERROR: no make_unique overload
std::unique_ptr<FILE, FileCloser> pFile(fopen("data.txt", "r"), FileCloser()); // OK: Direct construction

// Case 2: Braced initializers - make functions not applicable
auto pVec = std::make_unique<std::vector<int>>({1, 2, 3}); // ERROR in C++11/14, OK in C++17+
std::unique_ptr<std::vector<int>> pVecDirect(new std::vector<int>{1, 2, 3}); // OK: Direct construction

// Case 3: Exception-safety issue with direct 'new' (the problem make_shared solves)
class Widget {};
int computePriority() { throw std::runtime_error("failure"); return 0; }

// Potentially leaks new Widget if computePriority throws
// processWidget(std::shared_ptr<Widget>(new Widget()), computePriority()); 

// Safe way if not using make_shared
std::shared_ptr<Widget> spw(new Widget());
// processWidget(spw, computePriority()); // Safe, but less efficient (copy vs move)
